INSERT INTO `posts` (`id`, `category_id`, `type`, `title_id`, `title_en`, `slug`, `content_id`, `content_en`, `excerpt_id`, `excerpt_en`, `cover_image`, `is_headline`, `status`, `published_at`, `scheduled_at`, `meta_title_id`, `meta_title_en`, `meta_description_id`, `meta_description_en`, `og_image`, `canonical_url`, `robots`, `jsonld`) VALUES (1, NULL, 'berita', 'Penerapan Injeksi Presisi Mikro pada Komponen Medis', 'Micro-Precision Injection Molding for Medical Components', 'penerapan-injeksi-presisi-mikro-komponen-medis', 'PT Euodoo terus meningkatkan kapabilitas lini manufaktur dengan menghadirkan teknologi cetak presisi mikro. Standar ruang bersih (cleanroom) dan pengawasan visual optik terintegrasi memastikan produk bebas kontaminan dan memenuhi standar keselamatan ketat.', 'PT Euodoo continues to enhance manufacturing capabilities with micro-precision molding technology. Cleanroom standards and integrated optical inspection ensure contaminant-free products adhering to strict safety protocols.', 'Standardisasi kontrol dimensi dan ruang steril dalam produksi alat medis plastik presisi tinggi.', 'Dimensional control and cleanroom standards in high-precision medical plastic component production.', NULL, 0, 'published', '2026-09-29 14:07:56', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'index', NULL) ON DUPLICATE KEY UPDATE `id` = VALUES(`id`), `category_id` = VALUES(`category_id`), `type` = VALUES(`type`), `title_id` = VALUES(`title_id`), `title_en` = VALUES(`title_en`), `slug` = VALUES(`slug`), `content_id` = VALUES(`content_id`), `content_en` = VALUES(`content_en`), `excerpt_id` = VALUES(`excerpt_id`), `excerpt_en` = VALUES(`excerpt_en`), `cover_image` = VALUES(`cover_image`), `is_headline` = VALUES(`is_headline`), `status` = VALUES(`status`), `published_at` = VALUES(`published_at`), `scheduled_at` = VALUES(`scheduled_at`), `meta_title_id` = VALUES(`meta_title_id`), `meta_title_en` = VALUES(`meta_title_en`), `meta_description_id` = VALUES(`meta_description_id`), `meta_description_en` = VALUES(`meta_description_en`), `og_image` = VALUES(`og_image`), `canonical_url` = VALUES(`canonical_url`), `robots` = VALUES(`robots`), `jsonld` = VALUES(`jsonld`);
INSERT INTO `posts` (`id`, `category_id`, `type`, `title_id`, `title_en`, `slug`, `content_id`, `content_en`, `excerpt_id`, `excerpt_en`, `cover_image`, `is_headline`, `status`, `published_at`, `scheduled_at`, `meta_title_id`, `meta_title_en`, `meta_description_id`, `meta_description_en`, `og_image`, `canonical_url`, `robots`, `jsonld`) VALUES (2, 1, 'berita', 'PT Euodoo Raih Sertifikasi Ekolabel Indonesia SNI 7188.7:2011 untuk Seluruh Lini Kantong Belanja', 'PT Euodoo Achieves Indonesian Eco-Label SNI 7188.7:2011 Certification Across All Shopping Bag Lines', 'pt-euodoo-raih-sertifikasi-ekolabel-indonesia-sni-7188', '<p>Sebagai wujud komitmen berkelanjutan terhadap kelestarian lingkungan dan kepatuhan regulasi industri, PT EUODOO secara resmi meraih sertifikasi Ekolabel Indonesia SNI 7188.7:2011 dari Badan Standardisasi Nasional.</p>\r\n<p>Sertifikasi ini memvalidasi seluruh produk kantong belanja plastik mudah terurai secara alami tanpa meninggalkan residu mikroplastik berbahaya bagi ekosistem tanah maupun air.</p>\r\n<p><img src=\"../../../uploads/media/media-1793239589147-498125388.webp\" alt=\"WhatsApp Image 2026-10-29 at 07.34.53.jpeg\" width=\"314\" height=\"418\" /></p>', '<p>Demonstrating our enduring commitment to environmental sustainability and industrial compliance, PT EUODOO has officially received the Indonesian Eco-label SNI 7188.7:2011 certification from the National Standardization Agency.</p>\r\n<p>This certification validates our plastic shopping bags degradability standards without generating harmful microplastic residues.</p>', 'Komitmen nyata manufaktur plastik berkelanjutan dengan sertifikasi resmi standar nasional kantong belanja mudah terurai.', 'Concrete commitment to sustainable plastic manufacturing with official national accreditation for degradable bags.', '/uploads/posts/posts-1791441084801-22288020.webp', 1, 'published', '2026-09-15 09:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'index', NULL) ON DUPLICATE KEY UPDATE `id` = VALUES(`id`), `category_id` = VALUES(`category_id`), `type` = VALUES(`type`), `title_id` = VALUES(`title_id`), `title_en` = VALUES(`title_en`), `slug` = VALUES(`slug`), `content_id` = VALUES(`content_id`), `content_en` = VALUES(`content_en`), `excerpt_id` = VALUES(`excerpt_id`), `excerpt_en` = VALUES(`excerpt_en`), `cover_image` = VALUES(`cover_image`), `is_headline` = VALUES(`is_headline`), `status` = VALUES(`status`), `published_at` = VALUES(`published_at`), `scheduled_at` = VALUES(`scheduled_at`), `meta_title_id` = VALUES(`meta_title_id`), `meta_title_en` = VALUES(`meta_title_en`), `meta_description_id` = VALUES(`meta_description_id`), `meta_description_en` = VALUES(`meta_description_en`), `og_image` = VALUES(`og_image`), `canonical_url` = VALUES(`canonical_url`), `robots` = VALUES(`robots`), `jsonld` = VALUES(`jsonld`);
INSERT INTO `posts` (`id`, `category_id`, `type`, `title_id`, `title_en`, `slug`, `content_id`, `content_en`, `excerpt_id`, `excerpt_en`, `cover_image`, `is_headline`, `status`, `published_at`, `scheduled_at`, `meta_title_id`, `meta_title_en`, `meta_description_id`, `meta_description_en`, `og_image`, `canonical_url`, `robots`, `jsonld`) VALUES (3, 2, 'berita', 'Modernisasi Lini Ekstrusi Film di Pabrik Cigondewah Tingkatkan Kapasitas Produksi 500 Ton', 'Film Extrusion Line Modernization at Cigondewah Plant Boosts Production Capacity to 500 Tons', 'modernisasi-lini-ekstrusi-film-pabrik-cigondewah', '<p>PT EUODOO merampungkan instalasi mesin blowing ekstrusi film otomatis generasi terbaru di fasilitas pabrik Cigondewah, Bandung. Investasi ini meningkatkan total kapasitas produksi bulanan mencapai 500 ton untuk memenuhi lonjakan permintaan mitra ritel modern nasional.</p>', '<p>PT EUODOO has finalized the commissioning of advanced blown film extrusion lines at our Cigondewah manufacturing plant in Bandung, expanding monthly capacity to 500 metric tons to meet growing national retail demands.</p>', 'Peningkatan kapasitas produksi bulanan untuk menunjang kebutuhan mitra ritel modern dan sektor industri skala besar.', 'Expanding monthly production capacity to serve modern retail partners and large-scale industrial sectors.', '/uploads/media/media-1791277503210-837070134.webp', 1, 'published', '2026-09-20 10:30:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'index', NULL) ON DUPLICATE KEY UPDATE `id` = VALUES(`id`), `category_id` = VALUES(`category_id`), `type` = VALUES(`type`), `title_id` = VALUES(`title_id`), `title_en` = VALUES(`title_en`), `slug` = VALUES(`slug`), `content_id` = VALUES(`content_id`), `content_en` = VALUES(`content_en`), `excerpt_id` = VALUES(`excerpt_id`), `excerpt_en` = VALUES(`excerpt_en`), `cover_image` = VALUES(`cover_image`), `is_headline` = VALUES(`is_headline`), `status` = VALUES(`status`), `published_at` = VALUES(`published_at`), `scheduled_at` = VALUES(`scheduled_at`), `meta_title_id` = VALUES(`meta_title_id`), `meta_title_en` = VALUES(`meta_title_en`), `meta_description_id` = VALUES(`meta_description_id`), `meta_description_en` = VALUES(`meta_description_en`), `og_image` = VALUES(`og_image`), `canonical_url` = VALUES(`canonical_url`), `robots` = VALUES(`robots`), `jsonld` = VALUES(`jsonld`);
INSERT INTO `posts` (`id`, `category_id`, `type`, `title_id`, `title_en`, `slug`, `content_id`, `content_en`, `excerpt_id`, `excerpt_en`, `cover_image`, `is_headline`, `status`, `published_at`, `scheduled_at`, `meta_title_id`, `meta_title_en`, `meta_description_id`, `meta_description_en`, `og_image`, `canonical_url`, `robots`, `jsonld`) VALUES (4, NULL, 'pers', 'Siaran Pers Resmi: Komitmen Pasokan Kemasan Ramah Lingkungan PT Euodoo Menyambut Regulasi Baru 2026', 'Official Press Release: PT Euodoo Eco-Packaging Supply Readiness Supporting 2026 Regulations', 'siaran-pers-komitmen-pasokan-kemasan-ramah-lingkungan-2026', '<p>Jakarta, PT EUODOO menegaskan kesiapan penuh rantai pasok dalam mendukung peraturan pembatasan kantong plastik sekali pakai melalui penyediaan kantong 100% degradable berstandar Ekolabel Indonesia untuk seluruh mitra pasar modern.</p>', '<p>Jakarta, PT EUODOO reaffirms full supply chain readiness supporting national single-use plastic reduction policies through certified 100% degradable packaging for modern retail partners.</p>', 'Kesiapan pasokan kantong degradable terstandarisasi untuk mendukung inisiatif pengurangan sampah plastik nasional.', 'Standardized degradable bag supply readiness supporting national plastic waste reduction initiatives.', '/images/hero-factory-precision.webp', 1, 'published', '2026-09-25 14:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'index', NULL) ON DUPLICATE KEY UPDATE `id` = VALUES(`id`), `category_id` = VALUES(`category_id`), `type` = VALUES(`type`), `title_id` = VALUES(`title_id`), `title_en` = VALUES(`title_en`), `slug` = VALUES(`slug`), `content_id` = VALUES(`content_id`), `content_en` = VALUES(`content_en`), `excerpt_id` = VALUES(`excerpt_id`), `excerpt_en` = VALUES(`excerpt_en`), `cover_image` = VALUES(`cover_image`), `is_headline` = VALUES(`is_headline`), `status` = VALUES(`status`), `published_at` = VALUES(`published_at`), `scheduled_at` = VALUES(`scheduled_at`), `meta_title_id` = VALUES(`meta_title_id`), `meta_title_en` = VALUES(`meta_title_en`), `meta_description_id` = VALUES(`meta_description_id`), `meta_description_en` = VALUES(`meta_description_en`), `og_image` = VALUES(`og_image`), `canonical_url` = VALUES(`canonical_url`), `robots` = VALUES(`robots`), `jsonld` = VALUES(`jsonld`);
INSERT INTO `posts` (`id`, `category_id`, `type`, `title_id`, `title_en`, `slug`, `content_id`, `content_en`, `excerpt_id`, `excerpt_en`, `cover_image`, `is_headline`, `status`, `published_at`, `scheduled_at`, `meta_title_id`, `meta_title_en`, `meta_description_id`, `meta_description_en`, `og_image`, `canonical_url`, `robots`, `jsonld`) VALUES (5, 3, 'blog', 'Mengenal Teknologi OXIUM: Solusi Kantong Plastik Oxo-Biodegradable untuk Retail Berkelanjutan', 'Understanding OXIUM Technology: Oxo-Biodegradable Plastic Solutions for Sustainable Retail', 'mengenal-teknologi-oxium-plastik-biodegradable', '<p>Teknologi aditif degradasi OXIUM memungkinkan rantai polimer plastik terurai secara fotooksidasi dan biodegradasi alami dalam kurun waktu 24 hingga 36 bulan, tanpa mengorbankan daya tahan beban saat digunakan oleh konsumen.</p>', '<p>OXIUM degradable additive technology facilitates photo-oxidation and natural biodegradation of plastic polymer chains within 24 to 36 months, preserving high mechanical tensile strength during consumer usage.</p>', 'Ulasan ilmiah mengenai cara kerja aditif OXIUM dalam mempercepat penguraian kantong belanja secara aman dan higienis.', 'Scientific breakdown of how OXIUM additives accelerate plastic bag degradation safely and hygienically.', '/images/hero-factory-precision.webp', 1, 'published', '2026-09-28 11:15:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'index', NULL) ON DUPLICATE KEY UPDATE `id` = VALUES(`id`), `category_id` = VALUES(`category_id`), `type` = VALUES(`type`), `title_id` = VALUES(`title_id`), `title_en` = VALUES(`title_en`), `slug` = VALUES(`slug`), `content_id` = VALUES(`content_id`), `content_en` = VALUES(`content_en`), `excerpt_id` = VALUES(`excerpt_id`), `excerpt_en` = VALUES(`excerpt_en`), `cover_image` = VALUES(`cover_image`), `is_headline` = VALUES(`is_headline`), `status` = VALUES(`status`), `published_at` = VALUES(`published_at`), `scheduled_at` = VALUES(`scheduled_at`), `meta_title_id` = VALUES(`meta_title_id`), `meta_title_en` = VALUES(`meta_title_en`), `meta_description_id` = VALUES(`meta_description_id`), `meta_description_en` = VALUES(`meta_description_en`), `og_image` = VALUES(`og_image`), `canonical_url` = VALUES(`canonical_url`), `robots` = VALUES(`robots`), `jsonld` = VALUES(`jsonld`);
INSERT INTO `pages` (`id`, `slug`, `title_id`, `title_en`, `content_id`, `content_en`, `hero_image`, `meta_title_id`, `meta_title_en`, `meta_description_id`, `meta_description_en`, `og_image`, `canonical_url`, `robots`, `jsonld`) VALUES (1, 'about', 'Tentang PT Euodoo - Profil, Visi, Misi & Dedikasi Manufaktur', 'About PT Euodoo - Profile, Vision, Mission & Manufacturing Dedication', 'PT. EUODOO adalah perusahaan manufaktur kantong plastik HDPE dan LLDPE terkemuka yang berbasis di Cigondewah Bandung sejak 1990 dengan komitmen pada produk ramah lingkungan.', 'PT. EUODOO is a leading manufacturer of HDPE and LLDPE plastic bags based in Cigondewah Bandung since 1990, dedicated to eco-friendly 100% degradable solutions.', '/images/hero-factory-precision.webp', 'Tentang Kami | PT Euodoo Manufaktur Plastik Ramah Lingkungan', 'About Us | PT Euodoo Eco-Friendly Plastic Manufacturer', 'Profil lengkap PT Euodoo, produsen kantong plastik ramah lingkungan 100% degradable sejak 1990 dengan pabrik di Cigondewah Bandung.', 'Comprehensive profile of PT Euodoo, 100% degradable eco-friendly plastic bag manufacturer since 1990 based in Cigondewah Bandung.', NULL, NULL, 'index', NULL) ON DUPLICATE KEY UPDATE `id` = VALUES(`id`), `slug` = VALUES(`slug`), `title_id` = VALUES(`title_id`), `title_en` = VALUES(`title_en`), `content_id` = VALUES(`content_id`), `content_en` = VALUES(`content_en`), `hero_image` = VALUES(`hero_image`), `meta_title_id` = VALUES(`meta_title_id`), `meta_title_en` = VALUES(`meta_title_en`), `meta_description_id` = VALUES(`meta_description_id`), `meta_description_en` = VALUES(`meta_description_en`), `og_image` = VALUES(`og_image`), `canonical_url` = VALUES(`canonical_url`), `robots` = VALUES(`robots`), `jsonld` = VALUES(`jsonld`);
