INSERT INTO `about_timeline` (`id`, `year_label_id`, `year_label_en`, `title_id`, `title_en`, `description_id`, `description_en`, `sort_order`, `is_active`) VALUES (1, '1990', '1990 — Inception', 'Kelahiran PT Sahabat Baru & PT Pelita Baru', 'Founding of Sahabat Baru & Pelita Baru', 'Bermula dari industri rumahan manufaktur plastik di Bandung dengan komitmen menghadirkan produk berkualitas dan harga terjangkau.', 'Started as a plastic manufacturing operation in Bandung committed to quality and fair value.', 1, 1) ON DUPLICATE KEY UPDATE `year_label_id` = VALUES(`year_label_id`), `year_label_en` = VALUES(`year_label_en`), `title_id` = VALUES(`title_id`), `title_en` = VALUES(`title_en`), `description_id` = VALUES(`description_id`), `description_en` = VALUES(`description_en`), `sort_order` = VALUES(`sort_order`), `is_active` = VALUES(`is_active`);
INSERT INTO `about_timeline` (`id`, `year_label_id`, `year_label_en`, `title_id`, `title_en`, `description_id`, `description_en`, `sort_order`, `is_active`) VALUES (2, '2000-an — Ekspansi', '2000s — Expansion', 'Modernisasi Fasilitas & Kantor Jakarta', 'Plant Modernization & Jakarta Office', 'Ekspansi kapasitas mesin converting otomatis dan pembukaan kantor pemasaran di Palmerah Jakarta untuk memperluas jangkauan ke ritel modern.', 'Expanded automated converting capacity and established Jakarta sales office for modern retail.', 2, 1) ON DUPLICATE KEY UPDATE `year_label_id` = VALUES(`year_label_id`), `year_label_en` = VALUES(`year_label_en`), `title_id` = VALUES(`title_id`), `title_en` = VALUES(`title_en`), `description_id` = VALUES(`description_id`), `description_en` = VALUES(`description_en`), `sort_order` = VALUES(`sort_order`), `is_active` = VALUES(`is_active`);
INSERT INTO `about_timeline` (`id`, `year_label_id`, `year_label_en`, `title_id`, `title_en`, `description_id`, `description_en`, `sort_order`, `is_active`) VALUES (3, 'Era Inovasi Hijau', 'Green Innovation Era', 'Pionir Plastik Ramah Lingkungan OXIUM', 'Pioneering OXIUM Degradable Tech', 'Menjadi pionir penerapan aditif ramah lingkungan OXIUM berstandar SNI 7188.7:2011 dan US ASTM D6954 untuk mengurangi dampak sampah plastik.', 'Pioneered OXIUM degradable additives compliant with SNI 7188.7:2011 and ASTM D6954 standards.', 3, 1) ON DUPLICATE KEY UPDATE `year_label_id` = VALUES(`year_label_id`), `year_label_en` = VALUES(`year_label_en`), `title_id` = VALUES(`title_id`), `title_en` = VALUES(`title_en`), `description_id` = VALUES(`description_id`), `description_en` = VALUES(`description_en`), `sort_order` = VALUES(`sort_order`), `is_active` = VALUES(`is_active`);
INSERT INTO `about_timeline` (`id`, `year_label_id`, `year_label_en`, `title_id`, `title_en`, `description_id`, `description_en`, `sort_order`, `is_active`) VALUES (4, 'Kini — Keberlanjutan', 'Present — Sustainable Reach', 'Skala Nasional', 'Sustainable Quality & National Scale', 'Menyatukan seluruh operasional di bawah PT EUODOO dengan kapasitas ribuan ton per tahun melayani sektor ritel, industri, dan pasar tradisional.', 'Consolidating all operations under PT EUODOO, serving retail, industrial, and traditional markets nationwide.', 4, 1) ON DUPLICATE KEY UPDATE `year_label_id` = VALUES(`year_label_id`), `year_label_en` = VALUES(`year_label_en`), `title_id` = VALUES(`title_id`), `title_en` = VALUES(`title_en`), `description_id` = VALUES(`description_id`), `description_en` = VALUES(`description_en`), `sort_order` = VALUES(`sort_order`), `is_active` = VALUES(`is_active`);
