INSERT INTO `settings` (`setting_key`, `setting_value`) VALUES ('about_values_json', '[{\"letter\":\"T\",\"title_id\":\"Takut Tuhan\",\"title_en\":\"Fear of God\",\"desc_id\":\"Menjadi dasar moral, etika, dan spiritual dalam setiap keputusan bisnis dan operasional perusahaan.\",\"desc_en\":\"The moral and spiritual cornerstone guiding every business decision and daily operation.\",\"image_url\":\"/images/hero-factory.jpg\",\"icon_key\":\"praying-hands\",\"sort_order\":1},{\"letter\":\"I\",\"title_id\":\"Integritas\",\"title_en\":\"Integrity\",\"desc_id\":\"Kejujuran, konsistensi mutu, dan tanggung jawab penuh atas komitmen kepada pelanggan dan mitra.\",\"desc_en\":\"Honesty, consistent quality, and total accountability to customers and partners.\",\"image_url\":\"/images/hero-factory-precision.webp\",\"icon_key\":\"shield-check\",\"sort_order\":2},{\"letter\":\"C\",\"title_id\":\"Komunikasi\",\"title_en\":\"Communication\",\"desc_id\":\"Keterbukaan, respon yang membangun dan cepat, serta budaya mendengarkan tanpa mencari kesalahan.\",\"desc_en\":\"Openness, constructive responses, and an open culture of listening without fault-finding.\",\"image_url\":\"/images/segment-sustainability.jpg\",\"icon_key\":\"chat-dots\",\"sort_order\":3},{\"letter\":\"K\",\"title_id\":\"Kasih\",\"title_en\":\"Love\",\"desc_id\":\"Kepedulian tulus terhadap kesejahteraan dan pendidikan karyawan, kepuasan pelanggan, serta kelestarian bumi.\",\"desc_en\":\"Genuine care for employee education and well-being, customer satisfaction, and planetary care.\",\"image_url\":\"/images/post-eco-community.jpg\",\"icon_key\":\"heart\",\"sort_order\":4},{\"letter\":\"E\",\"title_id\":\"Luar Biasa\",\"title_en\":\"Excellence\",\"desc_id\":\"Dedikasi menghadirkan standar mutu plastik degradable terbaik dengan toleransi presisi tinggi.\",\"desc_en\":\"Dedication to delivering peak degradable plastic standards with tight precision tolerance.\",\"image_url\":\"/images/segment-industrial.jpg\",\"icon_key\":\"star\",\"sort_order\":5},{\"letter\":\"T\",\"title_id\":\"Taat\",\"title_en\":\"Obedience\",\"desc_id\":\"Kepatuhan terhadap standar keamanan, regulasi kelestarian lingkungan, dan sertifikasi resmi.\",\"desc_en\":\"Adherence to safety standards, environmental regulations, and official certifications.\",\"image_url\":\"/images/segment-retail.jpg\",\"icon_key\":\"handshake\",\"sort_order\":6}]') ON DUPLICATE KEY UPDATE `setting_value` = VALUES(`setting_value`);
